#!/usr/bin/env python3
"""Per-line, per-glyph-cluster dominant ink colors.

usage: spans.py FILE [INSET] [MINGAP]
Prints for each detected text line a list of x-ranges with their dominant ink color.
Adjacent clusters with the same dominant color are merged.
"""
import sys, collections
_argv = sys.argv[1:]
sys.argv = ['pngtool', 'nop']
sys.path.insert(0, '/workspace/notes')
import io, contextlib
_buf = io.StringIO()
with contextlib.redirect_stdout(_buf):
    import pngtool as P

def dist(c, d):
    return max(abs(c[0]-d[0]), abs(c[1]-d[1]), abs(c[2]-d[2]))

def main():
    path = _argv[0]
    inset = int(_argv[1]) if len(_argv) > 1 else 6
    mingap = int(_argv[2]) if len(_argv) > 2 else 2
    img = P.load(path)
    w, h, nch, data = img
    bgc = P.px(img, w//2, h//2)
    THR = 30
    # find line bands
    bands = []; cur = None
    for y in range(inset, h-inset):
        n = sum(1 for x in range(inset, w-inset) if dist(P.px(img, x, y), bgc) > THR)
        if n:
            cur = [y, y] if cur is None else [cur[0], y]
        else:
            if cur is not None and y - cur[1] > 2:
                bands.append(cur); cur = None
    if cur: bands.append(cur)
    print("# %s size=%dx%d bg=%s lines=%d" % (path, w, h, P.hx(bgc), len(bands)))
    for k, (ya, yb) in enumerate(bands):
        # per-column dominant
        cols = []
        for x in range(inset, w-inset):
            best = None; bd = 0
            cnt = collections.Counter()
            for y in range(ya, yb+1):
                p = P.px(img, x, y)
                d = dist(p, bgc)
                if d > THR:
                    cnt[P.hx(p)] += 1
                    if d > bd: bd = d; best = P.hx(p)
            cols.append((best, cnt))
        # cluster: consecutive non-empty columns separated by >= mingap empties
        clusters = []; cur2 = None; gap = 0
        for i, (b, cnt) in enumerate(cols):
            if b is not None:
                if cur2 is None: cur2 = [i, i, collections.Counter()]
                cur2[1] = i; cur2[2].update(cnt); gap = 0
            else:
                if cur2 is not None:
                    gap += 1
                    if gap >= mingap:
                        clusters.append(cur2); cur2 = None
        if cur2: clusters.append(cur2)
        out = []
        for a, b, cnt in clusters:
            col = cnt.most_common(1)[0][0]
            out.append((a+inset, b+inset, col, sum(cnt.values())))
        # merge adjacent same-color
        merged = []
        for a, b, col, n in out:
            if merged and merged[-1][2] == col and a - merged[-1][1] <= 4:
                merged[-1] = (merged[-1][0], b, col, merged[-1][3]+n)
            else:
                merged.append((a, b, col, n))
        s = " | ".join("%s x%d-%d" % (col, a, b) for a, b, col, n in merged)
        print("L%-3d y=%3d..%-3d %s" % (k+1, ya, yb, s))

main()

